import { clubs, players, fixtures, leaderboard, achievements, gameweeks, currentGameweek, applyOverrides } from './data.js';
import { FORMATIONS, SQUAD_RULES, createInitialSquad, squadCost, validateSquad, recalcStartingXI, canTransfer, fixtureDifficulty } from './domain.js';
import { createStore, loadState } from './state.js';
import { createTranslator } from './i18n.js';
import { icon } from './icons.js';

const root=document.getElementById('app');
const store=createStore(loadState());
let t=createTranslator(store.get().language);
let authMode='login', playerSheetId=null, transferIncomingId=null, leagueDialog=null, installPrompt=null, toastTimer=null, matchTick=0, activeModalKeyHandler=null;
const clubMap=Object.fromEntries(clubs.map(c=>[c.id,c]));
const playerMap=Object.fromEntries(players.map(p=>[p.id,p]));

function escapeHtml(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function money(n){return `₺${Number(n).toFixed(1)}m`;}
function rank(n){return new Intl.NumberFormat(store.get().language==='tr'?'tr-TR':'en-US').format(n);}
function statusText(s){return t(s==='available'?'available':s==='injury'?'injury':s==='suspended'?'suspended':'doubtful');}
function statusClass(s){return s==='available'?'ok':s==='doubtful'?'warn':'bad';}
function posText(p){return t(p==='GK'?'gk':p==='DEF'?'def':p==='MID'?'mid':'fwd');}
function clubBadge(id,small=false){const c=clubMap[id];return `<span class="club-badge ${small?'sm':''}" style="--club:${c.primary};--club2:${c.secondary}" aria-label="${escapeHtml(c.name)}"><span>${c.short.slice(0,2)}</span></span>`}
function haptic(){try{navigator.vibrate?.(8)}catch{}}
function playTone(kind='tap'){
 if(!store.get().sounds)return; try{const C=window.AudioContext||window.webkitAudioContext; const ctx=new C(); const o=ctx.createOscillator(),g=ctx.createGain(); o.connect(g);g.connect(ctx.destination); o.frequency.value=kind==='success'?740:kind==='goal'?520:340;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.start();o.stop(ctx.currentTime+.13);}catch{}
}
function toast(message,type='success'){clearTimeout(toastTimer); let el=document.getElementById('toast'); if(!el){el=document.createElement('div');el.id='toast';document.body.appendChild(el)} el.className=`toast show ${type}`;el.innerHTML=`${icon(type==='success'?'check':'alert',18)}<span>${escapeHtml(message)}</span>`; toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function applyPreferences(){const s=store.get(); t=createTranslator(s.language);document.documentElement.lang=s.language;document.documentElement.dataset.theme=s.theme;document.documentElement.classList.toggle('reduce-motion',s.reducedMotion);}

function ensureSquad(){const s=store.get(); if(s.squadIds.length===15)return; const ids=createInitialSquad(players); const formation=s.formation||'4-4-2'; const starting=recalcStartingXI(ids,formation,players,[]); const cost=squadCost(ids,players); store.set({squadIds:ids,startingIds:starting,captainId:starting.find(id=>playerMap[id]?.position==='FWD')||starting[0],viceCaptainId:starting.find(id=>playerMap[id]?.position==='MID')||starting[1],budget:Math.max(0,Math.round((SQUAD_RULES.initialBudget-cost)*10)/10)});}

async function requestFullscreen(){
 try{if(document.documentElement.requestFullscreen){await document.documentElement.requestFullscreen(); localStorage.setItem('sahanova.entered','1'); renderAuthOrApp();}
 else {document.body.classList.add('immersive-fallback'); localStorage.setItem('sahanova.entered','1'); toast(t('fullscreenUnsupported'),'error'); renderAuthOrApp();}}
 catch{document.body.classList.add('immersive-fallback'); localStorage.setItem('sahanova.entered','1'); renderAuthOrApp();}
}
function renderGate(){root.innerHTML=`<main class="gate-shell">
 <div class="stadium-bg" aria-hidden="true"><div class="light l1"></div><div class="light l2"></div><div class="pitch-lines"></div><div class="float-ball b1">⚽</div><div class="float-ball b2">•</div><div class="float-ball b3">•</div></div>
 <section class="gate-card"><img src="/assets/logo-mark.svg" class="gate-logo" alt="SahaNova"><div class="eyebrow">${t('fantasyFootball')}</div><h1>SAHA<span>NOVA</span></h1><p>${t('appTagline')}</p><button class="primary huge" id="enter-fullscreen">${icon('spark',22)}<span>${t('enterFullscreen')}</span></button><small>${t('enterHint')}</small><div class="gate-strip"><span>15 ${t('players')}</span><i></i><span>${t('live')}</span><i></i><span>${t('pwa')}</span></div></section>
 </main>`;document.getElementById('enter-fullscreen').onclick=()=>{haptic();requestFullscreen()};}

function renderAuthOrApp(){ensureSquad(); const s=store.get(); if(!s.session) renderAuth(); else if(!s.onboardingDone) renderOnboarding(0,{}); else renderApp();}
function renderAuth(){root.innerHTML=`<main class="auth-shell"><div class="auth-art"><img src="/assets/logo-mark.svg" alt=""><div><div class="eyebrow">SAHANOVA</div><h2>${t('appTagline')}</h2><p>${t('demoDisclaimer')}</p></div></div><section class="auth-card"><div class="auth-brand"><img src="/assets/logo-mark.svg" alt="SahaNova"><strong>SahaNova</strong></div>
 <div class="segmented auth-tabs"><button class="${authMode==='login'?'active':''}" data-auth="login">${t('login')}</button><button class="${authMode==='signup'?'active':''}" data-auth="signup">${t('signup')}</button><button class="${authMode==='forgot'?'active':''}" data-auth="forgot">${t('forgot')}</button></div>${authForm()}</section></main>`;
 document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{authMode=b.dataset.auth;renderAuth()});
 const form=document.getElementById('auth-form'); if(form) form.onsubmit=handleAuth;
 const demo=document.getElementById('demo-login');if(demo)demo.onclick=()=>loginDemo(false);
}
function authForm(){if(authMode==='forgot')return `<form id="auth-form" class="form-stack"><label>${t('email')}<input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></label><button class="primary" type="submit">${t('sendReset')}</button><p class="form-note">${t('authHint')}</p></form>`;
 return `<form id="auth-form" class="form-stack">${authMode==='signup'?`<label>${t('displayName')}<input name="name" required maxlength="40" placeholder="${t('signupPlaceholder')}"></label>`:''}<label>${t('email')}<input name="email" type="email" required autocomplete="email" placeholder="demo@sahanova.local"></label><label>${t('password')}<input name="password" type="password" minlength="6" required autocomplete="${authMode==='login'?'current-password':'new-password'}" placeholder="••••••••"></label><button class="primary" type="submit">${authMode==='login'?t('login'):t('signup')}</button><button class="secondary" type="button" id="demo-login">${icon('ball',20)}${t('continueDemo')}</button><p class="form-note">${t('authHint')}</p></form>`}
async function handleAuth(e){e.preventDefault();const fd=new FormData(e.currentTarget); const payload={email:fd.get('email'),password:fd.get('password'),name:fd.get('name')};if(authMode==='forgot'){toast(t('forgotSimulated'));return}
 try{const r=await fetch(`/api/auth/${authMode}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}); if(!r.ok)throw new Error(); const data=await r.json(); store.set({session:data.user,onboardingDone:authMode==='login'&&data.user.email==='demo@sahanova.local'?store.get().onboardingDone:false});playTone('success');renderAuthOrApp();}
 catch{ if(authMode==='login'&&payload.email==='demo@sahanova.local'&&payload.password==='demo1234')return loginDemo(false); if(authMode==='signup'){store.set({session:{id:'local-'+Date.now(),email:String(payload.email),displayName:String(payload.name||t('managerDefault')),role:'manager'}});renderAuthOrApp();} else toast(t('error'),'error');}}
function loginDemo(admin=false){store.set({session:{id:admin?'demo-admin':'demo-user',email:admin?'admin@sahanova.local':'demo@sahanova.local',displayName:admin?'SahaNova Admin':'SahaNova Demo',role:admin?'admin':'manager'}});playTone('success');renderAuthOrApp();}

function renderOnboarding(step=0,draft={}){const s=store.get(); const steps=[t('welcome'),t('chooseClub'),t('buildSquad'),t('chooseFormation'),t('chooseCaptain'),t('teamName'),t('confirmation')]; const d={favoriteClub:s.favoriteClub,formation:s.formation,captainId:s.captainId,teamName:s.teamName,...draft};
 root.innerHTML=`<main class="onboard-shell"><div class="onboard-top"><img src="/assets/logo-mark.svg" alt=""><div class="progress"><div style="width:${((step+1)/steps.length)*100}%"></div></div><span>${step+1}/${steps.length}</span></div><section class="onboard-card"><div class="step-kicker">${escapeHtml(steps[step])}</div>${onboardBody(step,d)}<div class="onboard-actions">${step>0?`<button class="secondary" id="ob-back">${t('back')}</button>`:''}<button class="primary" id="ob-next">${step===steps.length-1?t('finish'):t('next')}${icon('chevron',18)}</button></div></section></main>`;
 document.getElementById('ob-back')?.addEventListener('click',()=>renderOnboarding(step-1,d));document.getElementById('ob-next').onclick=()=>{const next=readOnboardDraft(d);if(step===steps.length-1){const starting=recalcStartingXI(s.squadIds,next.formation,players,s.startingIds);store.set({...next,startingIds:starting,captainId:next.captainId||starting[0],onboardingDone:true});playTone('success');renderApp();}else renderOnboarding(step+1,next)};
 document.querySelectorAll('[data-ob-club]').forEach(x=>x.onclick=()=>{document.querySelectorAll('[data-ob-club]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected')});document.querySelectorAll('[data-ob-form]').forEach(x=>x.onclick=()=>{document.querySelectorAll('[data-ob-form]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected')});document.querySelectorAll('[data-ob-cap]').forEach(x=>x.onclick=()=>{document.querySelectorAll('[data-ob-cap]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected')});}
function onboardBody(step,d){const s=store.get();if(step===0)return `<div class="ob-hero"><div class="orbit-ball">⚽</div><h1>${t('welcome')}, ${escapeHtml(s.session?.displayName||t('managerDefault'))}</h1><p>${t('onboardingIntro')}</p></div>`;
 if(step===1)return `<h2>${t('chooseClub')}</h2><div class="club-grid">${clubs.map(c=>`<button data-ob-club="${c.id}" class="club-choice ${d.favoriteClub===c.id?'selected':''}">${clubBadge(c.id)}<span>${c.name}</span></button>`).join('')}</div>`;
 if(step===2)return `<h2>${t('buildSquad')}</h2><div class="squad-ready"><div class="big-number">15</div><div><strong>${t('players')}</strong><p>${t('onboardingSquadHint')}</p></div></div><div class="mini-roster">${['GK','DEF','MID','FWD'].map(p=>`<div><span>${posText(p)}</span><b>${s.squadIds.filter(id=>playerMap[id].position===p).length}</b></div>`).join('')}</div>`;
 if(step===3)return `<h2>${t('chooseFormation')}</h2><div class="formation-grid">${Object.keys(FORMATIONS).map(f=>`<button data-ob-form="${f}" class="formation-choice ${d.formation===f?'selected':''}"><span class="formation-dots">${formationDots(f)}</span><b>${f}</b></button>`).join('')}</div>`;
 if(step===4){const starters=recalcStartingXI(s.squadIds,d.formation,players,s.startingIds);return `<h2>${t('chooseCaptain')}</h2><div class="captain-list">${starters.filter(id=>playerMap[id].position!=='GK').slice(0,8).map(id=>{const p=playerMap[id];return `<button data-ob-cap="${id}" class="captain-choice ${d.captainId===id?'selected':''}">${clubBadge(p.clubId,true)}<span><b>${p.name}</b><small>${posText(p.position)} · ${p.form} ${t('form')}</small></span>${icon('crown',20)}</button>`}).join('')}</div>`}
 if(step===5)return `<h2>${t('teamName')}</h2><div class="name-preview"><div class="jersey-icon">11</div><input id="ob-team-name" value="${escapeHtml(d.teamName)}" maxlength="24" aria-label="${t('teamName')}"><small>${t('nameLengthHint')}</small></div>`;
 return `<div class="ob-confirm"><div class="success-ring">${icon('check',44)}</div><h1>${escapeHtml(d.teamName)}</h1><p>${clubBadge(d.favoriteClub,true)} ${escapeHtml(clubMap[d.favoriteClub].name)} · ${d.formation}</p><div class="confirm-stats"><span><b>15</b>${t('players')}</span><span><b>${money(store.get().budget)}</b>${t('budget')}</span><span><b>${playerMap[d.captainId]?.name.split(' ')[0]||'—'}</b>${t('captain')}</span></div></div>`;}
function readOnboardDraft(d){const selClub=document.querySelector('[data-ob-club].selected')?.dataset.obClub; const selForm=document.querySelector('[data-ob-form].selected')?.dataset.obForm;const selCap=document.querySelector('[data-ob-cap].selected')?.dataset.obCap;const name=document.getElementById('ob-team-name')?.value?.trim(); return {...d,...(selClub&&{favoriteClub:selClub}),...(selForm&&{formation:selForm}),...(selCap&&{captainId:selCap}),...(name&&{teamName:name})};}
function formationDots(f){const [d,m,a]=f.split('-').map(Number);return `<i></i>${Array(d).fill('<i></i>').join('')}${Array(m).fill('<i></i>').join('')}${Array(a).fill('<i></i>').join('')}`}

function renderApp(){applyPreferences(); const s=store.get(); document.body.classList.add('app-mode'); root.innerHTML=`<div class="app-shell"><aside class="side-nav"><div class="side-brand"><img src="/assets/logo-mark.svg" alt=""><span>SahaNova</span></div>${navItems(true)}<div class="side-profile">${avatar(s.session?.displayName)}<span><b>${escapeHtml(s.session?.displayName||t('managerDefault'))}</b><small>${escapeHtml(s.teamName)}</small></span></div></aside><div class="app-main"><header class="topbar"><button class="mobile-brand" data-nav="home"><img src="/assets/logo-mark.svg" alt="SahaNova"></button><div class="top-title"><span>${screenTitle()}</span><small>${t('gameweek')} ${currentGameweek}</small></div><div class="top-actions"><span class="data-badge">${t('demoData')}</span><button class="icon-btn" data-more="settings" aria-label="${t('settings')}">${icon('settings',20)}</button>${avatar(s.session?.displayName)}</div></header><div id="offline-banner" class="offline-banner ${navigator.onLine?'':'show'}">${icon('alert',18)}${t('offline')}</div><main class="screen" id="screen">${renderScreen()}</main><nav class="bottom-nav">${navItems(false)}</nav></div></div>${renderPlayerSheet()}${renderTransferModal()}${renderLeagueDialog()}<div id="fullscreen-banner" class="fullscreen-banner"><span>${t('returnFullscreen')}</span><button id="fs-return">${t('fullscreen')}</button></div>`;
 bindAppEvents();}
function navItems(side=false){const items=[['home','home',t('home')],['team','team',t('team')],['transfer','transfer',t('transfer')],['matches','matches',t('matches')],['more','more',t('more')]];return items.map(([key,ic,label])=>`<button class="nav-item ${store.get().screen===key?'active':''}" data-nav="${key}" aria-label="${label}">${icon(ic,side?21:22)}<span>${label}</span></button>`).join('')}
function screenTitle(){const s=store.get(); if(s.screen==='more'&&s.moreScreen)return t(s.moreScreen);return t(s.screen)}
function renderScreen(){const s=store.get(); if(s.screen==='home')return renderDashboard(); if(s.screen==='team')return renderTeam(); if(s.screen==='transfer')return renderTransfers(); if(s.screen==='matches')return renderMatches(); return renderMore();}

function countdown(){const gw=gameweeks.find(g=>g.id===currentGameweek); let ms=new Date(gw.deadline).getTime()-Date.now(); if(ms<0)ms=2*dayMs()+6*3600000;const d=Math.floor(ms/86400000),h=Math.floor(ms%86400000/3600000),m=Math.floor(ms%3600000/60000);return `${d}${t('dayShort')} ${String(h).padStart(2,'0')}${t('hourShort')} ${String(m).padStart(2,'0')}${t('minuteShort')}`;}
function dayMs(){return 86400000}
function renderDashboard(){const s=store.get(); const tops=[...players].sort((a,b)=>b.form-a.form).slice(0,4);const live=fixtures.filter(f=>f.status==='live');const upcoming=fixtures.filter(f=>['today','upcoming'].includes(f.status)).slice(0,3);const alerts=s.squadIds.map(id=>playerMap[id]).filter(p=>p.status!=='available');return `<section class="hero-panel"><div class="hero-glow"></div><div class="hero-head"><div><span class="eyebrow">${t('gameweek')} ${currentGameweek}</span><h1>${escapeHtml(s.teamName)}</h1></div><div class="deadline-chip">${icon('clock',17)}<span><small>${t('deadline')}</small><b id="deadline-count">${countdown()}</b></span></div></div><div class="score-lockup"><div><span>${t('weekPoints')}</span><strong>${s.weekPoints}</strong><small>+${Math.round(s.weekPoints*.31)} ${t('livePoints')}</small></div><div class="hero-rank"><span>${icon('rank',19)}${t('overallRank')}</span><b>#${rank(s.overallRank)}</b><small class="up">▲ 1.284</small></div></div><div class="hero-mini"><span>${icon('wallet',18)}${money(s.budget)} <small>${t('budget')}</small></span><span>${icon('transfer',18)}${s.transfersLeft} <small>${t('transfersLeft')}</small></span><span>${icon('crown',18)}${escapeHtml(playerMap[s.captainId]?.name.split(' ')[0]||'—')} <small>${t('captain')}</small></span></div></section>
 <div class="metric-grid"><article class="metric-card"><span>${t('totalPoints')}</span><b>${s.totalPoints}</b><small>▲ 36 ${t('thisWeekLower')}</small></article><article class="metric-card"><span>${t('miniLeagueRank')}</span><b>#${s.miniLeagueRank}</b><small>${s.leagues[0]?.name||'—'}</small></article><article class="metric-card accent"><span>${t('liveNow')}</span><b>${live.length}</b><small>${live.map(f=>`${clubMap[f.homeId].short}–${clubMap[f.awayId].short}`).join(' · ')}</small></article></div>
 <div class="dashboard-grid"><section class="panel"><div class="section-head"><div><span class="live-dot"></span><h2>${t('matchCenter')}</h2></div><button data-nav="matches">${t('seeAll')}${icon('chevron',16)}</button></div>${live.length?live.map(f=>matchRow(f,true)).join(''):`<div class="empty-state">${t('noFixtures')}</div>`}</section>
 <section class="panel"><div class="section-head"><h2>${t('upcomingFixtures')}</h2><button data-more="fixtures">${t('seeAll')}${icon('chevron',16)}</button></div><div class="fixture-stack">${upcoming.map(f=>fixtureRow(f)).join('')}</div></section>
 <section class="panel"><div class="section-head"><h2>${t('topPerformers')}</h2><button data-nav="transfer">${t('seeAll')}${icon('chevron',16)}</button></div><div class="performers">${tops.map((p,i)=>playerCompact(p,i+1)).join('')}</div></section>
 <section class="panel"><div class="section-head"><h2>${t('squadAlerts')}</h2></div>${alerts.length?alerts.map(p=>`<button class="alert-row" data-player="${p.id}">${clubBadge(p.clubId,true)}<span><b>${p.name}</b><small>${statusText(p.status)}</small></span><em class="status ${statusClass(p.status)}">${statusText(p.status)}</em></button>`).join(''):`<div class="healthy-state">${icon('shield',24)}<div><b>${t('squadReadyTitle')}</b><small>${t('squadReadyDesc')}</small></div></div>`}</section></div>`}
function matchRow(f,compact=false){const home=clubMap[f.homeId],away=clubMap[f.awayId];return `<button class="match-row ${f.status==='live'?'is-live':''}" data-match="${f.id}"><div class="match-status">${f.status==='live'?`<span>${f.minute+Math.floor(matchTick/2)}'</span>`:formatDate(f.start)}</div><div class="match-team"><span>${home.short}</span>${clubBadge(home.id,true)}</div><div class="score"><b>${f.homeScore}</b><i>:</i><b>${f.awayScore}</b></div><div class="match-team away">${clubBadge(away.id,true)}<span>${away.short}</span></div>${!compact?`<div class="match-meta">${f.events?.length||0} ${t('eventsLower')}</div>`:''}</button>`}
function fixtureRow(f){const home=clubMap[f.homeId],away=clubMap[f.awayId];return `<button class="fixture-row" data-match="${f.id}">${clubBadge(home.id,true)}<span class="fixture-team">${home.short}</span><span class="fixture-time"><b>${new Date(f.start).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</b><small>${formatDate(f.start)}</small></span><span class="fixture-team right">${away.short}</span>${clubBadge(away.id,true)}</button>`}
function playerCompact(p,i){return `<button class="player-compact" data-player="${p.id}"><span class="perform-rank">${i}</span>${clubBadge(p.clubId,true)}<span class="pc-name"><b>${p.name}</b><small>${posText(p.position)} · ${money(p.price)}</small></span><span class="pc-form"><b>${p.form}</b><small>${t('form')}</small></span></button>`}
function formatDate(iso){return new Date(iso).toLocaleDateString(store.get().language==='tr'?'tr-TR':'en-US',{day:'numeric',month:'short'});}

function renderTeam(){const s=store.get();const validation=validateSquad(s.squadIds,players); const byPos={GK:[],DEF:[],MID:[],FWD:[]};s.startingIds.forEach(id=>byPos[playerMap[id].position].push(id));const bench=s.squadIds.filter(id=>!s.startingIds.includes(id));return `<div class="team-toolbar"><div><span class="eyebrow">${t('formation')}</span><div class="formation-scroll">${Object.keys(FORMATIONS).map(f=>`<button class="formation-pill ${s.formation===f?'active':''}" data-formation="${f}">${f}</button>`).join('')}</div></div><div class="squad-budget"><span>${t('budget')}</span><b>${money(s.budget)}</b></div></div><section class="pitch-card"><div class="pitch-sheen"></div><div class="pitch-markings"><i class="half"></i><i class="circle"></i><i class="box top"></i><i class="box bottom"></i></div><div class="pitch-team">${['FWD','MID','DEF','GK'].map(pos=>`<div class="pitch-row pos-${pos.toLowerCase()}">${byPos[pos].map(id=>pitchPlayer(playerMap[id],s)).join('')}</div>`).join('')}</div></section><section class="bench-panel"><div class="section-head"><h2>${t('bench')}</h2><span class="validation ${validation.valid?'valid':'invalid'}">${icon(validation.valid?'check':'alert',16)}${validation.valid?t('squadValid'):t('invalidSquad')}</span></div><div class="bench-grid">${bench.map((id,i)=>benchPlayer(playerMap[id],i+1,s)).join('')}</div></section><div class="team-actions"><button class="secondary" id="save-squad">${icon('check',19)}${t('saveSquad')}</button><button class="primary" data-nav="transfer">${icon('transfer',19)}${t('transfer')}</button></div>`}
function pitchPlayer(p,s){const cap=s.captainId===p.id,vice=s.viceCaptainId===p.id;return `<button class="pitch-player ${p.status!=='available'?'flagged':''}" data-player="${p.id}" aria-label="${escapeHtml(p.name)}"><div class="player-token" style="--club:${clubMap[p.clubId].primary};--club2:${clubMap[p.clubId].secondary}"><span class="token-shirt">${p.position==='GK'?'1':'•'}</span>${cap?'<em class="captain-badge">C</em>':vice?'<em class="captain-badge vice">V</em>':''}${p.status!=='available'?`<em class="player-flag">!</em>`:''}</div><span class="player-name">${escapeHtml(p.name.split(' ').pop())}</span><small>${p.weekPoints} ${t('pointsAbbr')}</small></button>`}
function benchPlayer(p,i,s){return `<button class="bench-player" data-player="${p.id}"><span class="bench-num">${i}</span><div class="mini-shirt" style="--club:${clubMap[p.clubId].primary};--club2:${clubMap[p.clubId].secondary}"></div><span><b>${p.name}</b><small>${posText(p.position)} · ${p.weekPoints} ${t('pointsAbbr')}</small></span>${s.captainId===p.id?'<em>C</em>':''}</button>`}

function playerNextDifficulty(p){const f=fixtures.filter(x=>[x.homeId,x.awayId].includes(p.clubId)&&['today','upcoming'].includes(x.status)).sort((a,b)=>new Date(a.start)-new Date(b.start))[0];if(!f)return 3;const opp=f.homeId===p.clubId?clubMap[f.awayId]:clubMap[f.homeId];return fixtureDifficulty(clubMap[p.clubId].strength,opp.strength,f.homeId===p.clubId)}
function renderTransfers(){const s=store.get();return `<section class="transfer-head"><div><span class="eyebrow">${t('transfer')}</span><h1>${t('players')}</h1></div><div class="transfer-balance"><span>${t('budget')}</span><b>${money(s.budget)}</b><small>${s.transfersLeft} ${t('transfersLeft')}</small></div></section><div class="market-controls"><div class="searchbox">${icon('search',19)}<input id="player-search" placeholder="${t('searchPlayer')}" aria-label="${t('searchPlayer')}"></div><select id="filter-pos" aria-label="${t('position')}"><option value="">${t('allPositions')}</option><option value="GK">${t('gk')}</option><option value="DEF">${t('def')}</option><option value="MID">${t('mid')}</option><option value="FWD">${t('fwd')}</option></select><select id="filter-club" aria-label="${t('club')}"><option value="">${t('allTeams')}</option>${clubs.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><select id="sort-player" aria-label="${t('sort')}"><option value="points">${t('sortPoints')}</option><option value="price">${t('sortPrice')}</option><option value="form">${t('sortForm')}</option><option value="trendIn">${t('sortTransfersIn')}</option><option value="trendOut">${t('sortTransfersOut')}</option><option value="ownership">${t('sortOwnership')}</option><option value="value">${t('sortValue')}</option></select></div><div class="market-filters"><select id="filter-price" aria-label="${t('maxPrice')}"><option value="">${t('maxPrice')}</option><option value="5">≤ ₺5.0m</option><option value="6.5">≤ ₺6.5m</option><option value="8">≤ ₺8.0m</option><option value="10">≤ ₺10.0m</option></select><select id="filter-points" aria-label="${t('minPoints')}"><option value="">${t('minPoints')}</option><option value="50">≥ 50</option><option value="75">≥ 75</option><option value="100">≥ 100</option></select><select id="filter-form" aria-label="${t('minForm')}"><option value="">${t('minForm')}</option><option value="5">≥ 5.0</option><option value="7">≥ 7.0</option><option value="8">≥ 8.0</option></select><select id="filter-ownership" aria-label="${t('minOwnership')}"><option value="">${t('minOwnership')}</option><option value="5">≥ 5%</option><option value="15">≥ 15%</option><option value="25">≥ 25%</option></select><select id="filter-status" aria-label="${t('availability')}"><option value="">${t('allAvailability')}</option><option value="available">${t('available')}</option><option value="doubtful">${t('doubtful')}</option><option value="flagged">${t('flagged')}</option></select><select id="filter-difficulty" aria-label="${t('maxDifficulty')}"><option value="">${t('maxDifficulty')}</option>${[1,2,3,4,5].map(n=>`<option value="${n}">≤ ${n}</option>`).join('')}</select></div><div class="market-summary"><span><i class="status-dot ok"></i>${t('available')}</span><span><i class="status-dot warn"></i>${t('doubtful')}</span><span><i class="status-dot bad"></i>${t('injury')} / ${t('suspended')}</span></div><div id="player-market" class="player-market">${marketRows([...players].sort((a,b)=>b.totalPoints-a.totalPoints))}</div>`}
function marketRows(list){const squad=new Set(store.get().squadIds);return list.map(p=>{const diff=playerNextDifficulty(p);return `<article class="market-player ${squad.has(p.id)?'owned':''}"><button class="market-info" data-player="${p.id}">${clubBadge(p.clubId)}<span class="market-name"><b>${p.name}</b><small>${clubMap[p.clubId].short} · ${posText(p.position)} <i class="status-dot ${statusClass(p.status)}"></i> <em class="diff d${diff}" aria-label="${t('fixtureDifficultyAria')} ${diff}">${diff}</em></small></span><span class="market-stat"><b>${p.totalPoints}</b><small>${t('points')}</small></span><span class="market-stat"><b>${p.form}</b><small>${t('form')}</small></span><span class="market-stat hide-mobile"><b>${p.ownership}%</b><small>${t('ownership')}</small></span><span class="market-price"><b>${money(p.price)}</b><small>${p.trend>=0?'▲':'▼'} ${Math.abs(p.trend).toLocaleString()}</small></span></button><button class="add-player" data-buy="${p.id}" ${squad.has(p.id)?'disabled':''} aria-label="${t('buy')} ${escapeHtml(p.name)}">${squad.has(p.id)?icon('check',19):icon('plus',19)}</button></article>`}).join('')}
function filterMarket(){let list=[...players],q=document.getElementById('player-search')?.value.toLocaleLowerCase(store.get().language==='tr'?'tr':'en'),pos=document.getElementById('filter-pos')?.value,club=document.getElementById('filter-club')?.value,sort=document.getElementById('sort-player')?.value,maxPrice=Number(document.getElementById('filter-price')?.value||0),minPoints=Number(document.getElementById('filter-points')?.value||0),minForm=Number(document.getElementById('filter-form')?.value||0),minOwnership=Number(document.getElementById('filter-ownership')?.value||0),status=document.getElementById('filter-status')?.value,maxDifficulty=Number(document.getElementById('filter-difficulty')?.value||0);if(q)list=list.filter(p=>p.name.toLocaleLowerCase(store.get().language==='tr'?'tr':'en').includes(q));if(pos)list=list.filter(p=>p.position===pos);if(club)list=list.filter(p=>p.clubId===club);if(maxPrice)list=list.filter(p=>p.price<=maxPrice);if(minPoints)list=list.filter(p=>p.totalPoints>=minPoints);if(minForm)list=list.filter(p=>p.form>=minForm);if(minOwnership)list=list.filter(p=>p.ownership>=minOwnership);if(status)list=list.filter(p=>status==='flagged'?p.status!=='available':p.status===status);if(maxDifficulty)list=list.filter(p=>playerNextDifficulty(p)<=maxDifficulty);list.sort((a,b)=>sort==='price'?a.price-b.price:sort==='form'?b.form-a.form:sort==='trendIn'?b.trend-a.trend:sort==='trendOut'?a.trend-b.trend:sort==='ownership'?b.ownership-a.ownership:sort==='value'?b.value-a.value:b.totalPoints-a.totalPoints);document.getElementById('player-market').innerHTML=marketRows(list);bindDynamicMarket();}

function renderMatches(){const s=store.get();const tab=s.matchTab||'live';const map={live:'live',today:'today',upcoming:'upcoming',results:'result'};const list=fixtures.filter(f=>f.status===map[tab]);return `<section class="match-header"><div><span class="eyebrow">${t('matchCenter')}</span><h1>${t(tab)}</h1></div><div class="live-orb"><span></span>${fixtures.filter(f=>f.status==='live').length} ${t('live')}</div></section><div class="match-tabs segmented">${['live','today','upcoming','results'].map(k=>`<button data-match-tab="${k}" class="${tab===k?'active':''}">${t(k)}</button>`).join('')}</div><div class="match-list">${list.length?list.map(f=>matchCard(f)).join(''):`<div class="empty-state big">${icon('calendar',34)}<b>${t('noFixtures')}</b></div>`}</div>`}
function renderMatchEvent(e){if(e.type==='sub'){const out=playerMap[e.playerOutId],incoming=playerMap[e.playerInId];return `<span>${e.minute}' ↔ ${out?.name.split(' ').pop()||'—'} → ${incoming?.name.split(' ').pop()||'—'}</span>`}const p=playerMap[e.playerId],glyph=e.type==='goal'?'⚽':e.type==='red'?'🟥':'🟨';return `<span>${e.minute}' ${glyph} ${p?.name||''}</span>`}
function matchCard(f){const home=clubMap[f.homeId],away=clubMap[f.awayId];return `<article class="match-card ${f.status==='live'?'live-match':''}"><div class="match-card-top"><span>${f.status==='live'?`<b class="pulse-label">${t('statusLive')}</b> ${f.minute+Math.floor(matchTick/2)}'`:f.status==='result'?t('statusFt'):formatDate(f.start)}</span><span>${t('gameweek')} ${f.gameweek}</span></div><div class="match-scoreboard"><div class="match-club">${clubBadge(home.id)}<b>${home.name}</b></div><div class="big-score"><span>${f.homeScore}</span><i>:</i><span>${f.awayScore}</span><small>${f.status==='upcoming'||f.status==='today'?new Date(f.start).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):''}</small></div><div class="match-club">${clubBadge(away.id)}<b>${away.name}</b></div></div>${f.events?.length?`<div class="event-strip">${f.events.map(renderMatchEvent).join('')}</div>`:''}<div class="fantasy-live"><span>${t('fantasyPoints')}</span>${[...players].filter(p=>[f.homeId,f.awayId].includes(p.clubId)).sort((a,b)=>b.weekPoints-a.weekPoints).slice(0,3).map(p=>`<button data-player="${p.id}">${p.name.split(' ').pop()} <b>+${p.weekPoints}</b></button>`).join('')}</div></article>`}

function renderMore(){const s=store.get(); if(s.moreScreen==='fixtures')return renderFixtures();if(s.moreScreen==='leagues')return renderLeagues();if(s.moreScreen==='profile')return renderProfile();if(s.moreScreen==='achievements')return renderAchievements();if(s.moreScreen==='settings')return renderSettings();if(s.moreScreen==='admin')return renderAdminLink();return `<section class="more-hero"><div>${avatar(s.session?.displayName,'xl')}<span><h1>${escapeHtml(s.session?.displayName||t('managerDefault'))}</h1><p>${escapeHtml(s.teamName)}</p></span></div><b>#${rank(s.overallRank)}</b></section><div class="more-grid">${moreTile('fixtures','calendar',t('fixtures'),t('weeksDifficulty'))}${moreTile('leagues','trophy',t('leagues'),`${s.leagues.length} ${t('leaguesLower')}`)}${moreTile('profile','user',t('profile'),`${s.totalPoints} ${t('points')}`)}${moreTile('achievements','medal',t('achievements'),`${achievements.filter(a=>a.unlocked).length}/${achievements.length}`)}${moreTile('settings','settings',t('settings'),t('language'))}${moreTile('admin','shield',t('admin'),t('protectedArea'))}</div><p class="legal-note">${t('demoDisclaimer')}</p>`}
function moreTile(key,ic,title,sub){return `<button class="more-tile" data-more="${key}"><span class="tile-icon">${icon(ic,24)}</span><span><b>${title}</b><small>${sub}</small></span>${icon('chevron',18)}</button>`}
function fixtureTable(list){return `<div class="fixture-table">${list.length?list.map(f=>{const h=clubMap[f.homeId],a=clubMap[f.awayId],dh=fixtureDifficulty(h.strength,a.strength,true),da=fixtureDifficulty(h.strength,a.strength,false);return `<div class="fixture-table-row"><span>${formatDate(f.start)}</span><div>${clubBadge(h.id,true)}<b>${h.short}</b><em class="diff d${dh}" aria-label="${t('fixtureDifficultyAria')} ${dh}">${dh}</em></div><i>${t('versus')}</i><div><em class="diff d${da}" aria-label="${t('fixtureDifficultyAria')} ${da}">${da}</em><b>${a.short}</b>${clubBadge(a.id,true)}</div><span>${new Date(f.start).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span></div>`}).join(''):`<div class="empty-state big">${t('noFixtures')}</div>`}</div>`}
function renderFixtures(){const s=store.get(),week=s.fixtureWeek||currentGameweek,view=s.fixtureView||'current';let body='';if(view==='current'){const list=fixtures.filter(f=>f.gameweek===week);body=`<div class="week-switcher"><button data-week="${Math.max(4,week-1)}">‹</button><span><b>${t('gameweek')} ${week}</b><small>${week===currentGameweek?t('currentWeek'):t('futureWeeks')}</small></span><button data-week="${Math.min(6,week+1)}">›</button></div>${fixtureTable(list)}`}else if(view==='future'){const list=fixtures.filter(f=>f.gameweek>currentGameweek).sort((a,b)=>a.gameweek-b.gameweek||new Date(a.start)-new Date(b.start));body=fixtureTable(list)}else{const selected=s.fixtureClub||s.favoriteClub||clubs[0].id,list=fixtures.filter(f=>[f.homeId,f.awayId].includes(selected)).sort((a,b)=>new Date(a.start)-new Date(b.start));body=`<div class="fixture-club-filter"><select id="fixture-club" aria-label="${t('club')}">${clubs.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${c.name}</option>`).join('')}</select></div>${fixtureTable(list)}`}return backHeader('fixtures')+`<div class="fixture-view-tabs segmented">${[['current','currentWeek'],['future','futureWeeks'],['club','byClub']].map(([k,l])=>`<button data-fixture-view="${k}" class="${view===k?'active':''}">${t(l)}</button>`).join('')}</div>${body}`}
function leaderboardRows(rows,weekly=false){const sorted=weekly?[...rows].sort((a,b)=>b.week-a.week):rows;return sorted.map((r,i)=>`<div class="leader-row ${r.manager==='SahaNova Demo'?'me':''}"><span class="lr-rank">${weekly?i+1:r.rank}</span><span class="lr-change ${r.change>0?'up':r.change<0?'down':''}">${r.change>0?'▲':r.change<0?'▼':'—'}${r.change!==0?Math.abs(r.change):''}</span>${avatar(r.manager)}<span class="lr-name"><b>${r.manager}</b><small>${r.team}</small></span><span class="lr-week"><b>${r.week}</b><small>${t('weeklyScore')}</small></span><span class="lr-total"><b>${r.total}</b><small>${t('points')}</small></span></div>`).join('')}
function renderLeagues(){
 const s=store.get(),view=s.leagueView||'friends';
 let title=t('friendsLeague'),code='NOVA26',rankValue=s.miniLeagueRank,rows=leaderboard,extra='';
 if(view==='global'){
  title=t('globalLeague');code='GLOBAL';rankValue=rank(s.overallRank);
 }else if(view==='weekly'){
  title=t('weeklyRanking');code=`${t('gameweek')} ${currentGameweek}`;rows=[...leaderboard].sort((a,b)=>b.week-a.week);rankValue=rows.findIndex(r=>r.manager==='SahaNova Demo')+1;
 }else{
  const active=s.leagues.find(l=>l.id===s.activeLeagueId)||s.leagues[0];title=active?.name||t('friendsLeague');code=active?.code||'NOVA26';
  extra=s.leagues.length>1?`<div class="league-chips">${s.leagues.map(l=>`<button data-league-id="${l.id}" class="${l.id===active?.id?'active':''}">${escapeHtml(l.name)}</button>`).join('')}</div>`:'';
 }
 return backHeader('leagues')+`<div class="league-view-tabs segmented">${[['global','globalLeague'],['friends','friendsLeague'],['weekly','weeklyRanking']].map(([k,l])=>`<button data-league-view="${k}" class="${view===k?'active':''}">${t(l)}</button>`).join('')}</div><div class="league-actions"><button class="primary" data-league-dialog="create">${icon('plus',19)}${t('createLeague')}</button><button class="secondary" data-league-dialog="join">${icon('swap',19)}${t('joinLeague')}</button></div>${extra}<section class="league-card"><div class="league-card-head"><div><span class="eyebrow">${code}</span><h2>${escapeHtml(title)}</h2></div><div class="rank-bubble">#${rankValue}</div></div><div class="leaderboard">${leaderboardRows(rows,view==='weekly')}</div></section>`;
}
function renderProfile(){const s=store.get();return backHeader('profile')+`<section class="profile-hero">${avatar(s.session?.displayName,'xxl')}<h1>${escapeHtml(s.session?.displayName||t('managerDefault'))}</h1><p>${escapeHtml(s.teamName)}</p><div class="club-pill">${clubBadge(s.favoriteClub,true)}${clubMap[s.favoriteClub].name}</div></section><div class="profile-stats"><div><b>${s.totalPoints}</b><span>${t('totalPoints')}</span></div><div><b>89</b><span>${t('bestWeek')}</span></div><div><b>#${rank(s.overallRank)}</b><span>${t('overallRank')}</span></div></div><section class="panel"><div class="section-head"><h2>${t('leagueHistory')}</h2></div><div class="history-timeline"><div><i></i><span><b>2026 / 27</b><small>${t('activeSeason')} · 487 ${t('pointsAbbr')}</small></span></div><div><i></i><span><b>2025 / 26</b><small>#12.884 · 2.144 ${t('points')}</small></span></div></div></section>`}
function renderAchievements(){return backHeader('achievements')+`<div class="achievement-grid">${achievements.map(a=>`<article class="achievement ${a.unlocked?'unlocked':''}"><div class="ach-icon">${icon(a.icon,29)}</div><span><b>${t(a.id)}</b><small>${a.unlocked?t('unlocked'):`${a.progress}% · ${t('locked')}`}</small><i><em style="width:${a.progress}%"></em></i></span></article>`).join('')}</div>`}
function renderSettings(){const s=store.get();return backHeader('settings')+`<section class="settings-list"><div class="setting-row"><span>${icon('language',20)}<b>${t('language')}</b></span><select id="setting-language"><option value="tr" ${s.language==='tr'?'selected':''}>Türkçe</option><option value="en" ${s.language==='en'?'selected':''}>English</option></select></div><div class="setting-row"><span>${icon('moon',20)}<b>${t('theme')}</b></span><select id="setting-theme"><option value="dark" ${s.theme==='dark'?'selected':''}>${t('dark')}</option><option value="light" ${s.theme==='light'?'selected':''}>${t('light')}</option><option value="system" ${s.theme==='system'?'selected':''}>${t('system')}</option></select></div>${toggleSetting('sounds','spark',t('sounds'),s.sounds)}${toggleSetting('reducedMotion','clock',t('reducedMotion'),s.reducedMotion)}${toggleSetting('notifications','bell',t('notifications'),s.notifications)}<button class="setting-row button-row" id="setting-fullscreen"><span>${icon('spark',20)}<b>${t('fullscreen')}</b></span>${icon('chevron',18)}</button><button class="setting-row button-row" id="install-app"><span>${icon('download',20)}<b>${t('installApp')}</b></span>${icon('chevron',18)}</button><button class="setting-row button-row danger" id="logout"><span>${icon('logout',20)}<b>${t('logout')}</b></span>${icon('chevron',18)}</button></section><p class="legal-note">${t('demoDisclaimer')}</p>`}
function toggleSetting(key,ic,label,val){return `<label class="setting-row"><span>${icon(ic,20)}<b>${label}</b></span><input class="switch-input" type="checkbox" data-setting="${key}" ${val?'checked':''}><i class="switch"></i></label>`}
function renderAdminLink(){const s=store.get();return backHeader('admin')+`<section class="admin-teaser"><div class="admin-shield">${icon('shield',42)}</div><h2>${t('adminTitle')}</h2><p>${t('adminProtected')}</p>${s.session?.role==='admin'?`<a class="primary link-button" href="/admin/">${t('dataManagement')}</a>`:`<button class="primary" id="demo-admin-login">${t('adminLogin')}</button><small>${t('demoAdminHint')}</small>`}</section>`}

function renderPlayerSheet(){if(!playerSheetId)return '';const p=playerMap[playerSheetId],s=store.get(),owned=s.squadIds.includes(p.id);const nextFixtures=fixtures.filter(f=>[f.homeId,f.awayId].includes(p.clubId)&&['today','upcoming'].includes(f.status)).slice(0,3);return `<div class="sheet-backdrop" data-close-sheet></div><aside class="player-sheet" role="dialog" aria-modal="true" aria-label="${escapeHtml(p.name)}"><button class="sheet-close" data-close-sheet aria-label="${t('close')}">${icon('x',21)}</button><div class="player-hero"><div class="portrait" style="--club:${clubMap[p.clubId].primary};--club2:${clubMap[p.clubId].secondary}"><span>${p.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span></div><div><span class="eyebrow">${clubMap[p.clubId].name} · ${posText(p.position)}</span><h2>${p.name}</h2><div class="hero-tags"><em class="status ${statusClass(p.status)}">${statusText(p.status)}</em><span>${p.ownership}% ${t('ownership')}</span><span>${p.trend>=0?'▲':'▼'} ${Math.abs(p.trend).toLocaleString()} ${t('transferTrend')}</span></div></div><b class="sheet-price">${money(p.price)}</b></div><div class="sheet-kpis"><div><b>${p.weekPoints}</b><span>${t('weekPoints')}</span></div><div><b>${p.totalPoints}</b><span>${t('totalPoints')}</span></div><div><b>${p.form}</b><span>${t('form')}</span></div><div><b>${(p.totalPoints/Math.max(1,Math.round(p.minutes/90))).toFixed(1)}</b><span>${t('pointsPerMatch')}</span></div></div><div class="chart-card"><div class="section-head"><h3>${t('recentPoints')}</h3><span>${p.trend>=0?'▲':'▼'} ${Math.abs(p.trend).toLocaleString()}</span></div>${sparkline(p.recent,t('recentPoints'),'recent')}</div><div class="chart-card"><div class="section-head"><h3>${t('priceHistory')}</h3><span>${money(p.price)}</span></div>${sparkline(p.prices,t('priceHistory'),'price')}</div><div class="detail-stats">${statMini(t('minutes'),p.minutes)}${statMini(t('goal'),p.goals)}${statMini(t('assist'),p.assists)}${statMini(t('cleanSheet'),p.cleanSheets)}${p.position==='GK'?statMini(t('saves'),p.saves):''}${statMini(t('yellowCard'),p.yellow)}${statMini(t('redCard'),p.red)}</div><div class="sheet-fixtures"><h3>${t('upcomingFixtures')}</h3>${nextFixtures.map(f=>{const opp=f.homeId===p.clubId?clubMap[f.awayId]:clubMap[f.homeId];const isHome=f.homeId===p.clubId;const diff=fixtureDifficulty(clubMap[p.clubId].strength,opp.strength,isHome);return `<div>${clubBadge(opp.id,true)}<span><b>${opp.name}</b><small>${formatDate(f.start)} · ${isHome?t('homeShort'):t('awayShort')}</small></span><em class="diff d${diff}">${diff}</em></div>`}).join('')}</div><div class="sheet-actions">${owned?(s.startingIds.includes(p.id)?`<button class="secondary" data-captain="${p.id}">${icon('crown',18)}${t('makeCaptain')}</button><button class="secondary" data-vice="${p.id}">${t('makeVice')}</button><button class="primary" data-toggle-start="${p.id}">${t('moveBench')}</button>`:`<button class="primary" data-toggle-start="${p.id}">${t('moveStart')}</button>`):`<button class="primary" data-buy="${p.id}">${icon('plus',18)}${t('buy')}</button>`}</div></aside>`}
function statMini(label,val){return `<div><b>${val}</b><span>${label}</span></div>`}
function sparkline(values,label=t('recentPoints'),id='chart'){const w=320,h=88,max=Math.max(...values),min=Math.min(...values),pts=values.map((v,i)=>`${10+i*(300/(values.length-1))},${76-((v-min)/(max-min||1))*58}`).join(' '),gid=`chartFill-${id}`;return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}"><defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="currentColor" stop-opacity=".28"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><path d="M10 76 L${pts.replaceAll(' ',',')} L310 76 Z" fill="url(#${gid})" opacity=".55"/><polyline points="${pts}" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${10+i*(300/(values.length-1))}" cy="${76-((v-min)/(max-min||1))*58}" r="3.5" fill="currentColor"/>`).join('')}</svg>`}

function renderTransferModal(){if(!transferIncomingId)return '';const incoming=playerMap[transferIncomingId],s=store.get();const eligible=s.squadIds.map(id=>playerMap[id]).filter(p=>p.position===incoming.position);return `<div class="modal-backdrop" data-close-transfer></div><section class="modal transfer-modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="eyebrow">${t('transfer')}</span><h2>${t('replace')} ${incoming.name}</h2></div><button data-close-transfer aria-label="${t('close')}">${icon('x',20)}</button></div><div class="incoming-card">${clubBadge(incoming.clubId)}<span><b>${incoming.name}</b><small>${posText(incoming.position)} · ${incoming.totalPoints} ${t('points')}</small></span><strong>${money(incoming.price)}</strong></div><h3>${t('chooseOutgoing')}</h3><div class="replace-list">${eligible.map(out=>{const test=canTransfer({squadIds:s.squadIds,outId:out.id,inId:incoming.id,players,budget:s.budget});return `<button data-outgoing="${out.id}" class="replace-row ${test.ok?'':'disabled'}">${clubBadge(out.clubId,true)}<span><b>${out.name}</b><small>${money(out.price)} · ${out.totalPoints} ${t('points')}</small></span><em>${test.ok?`${test.nextBudget>=s.budget?'+':''}${(test.nextBudget-s.budget).toFixed(1)}m`:test.reason==='budget'?t('budgetExceeded'):test.reason==='club'?t('clubLimit'):t('transferRejected')}</em></button>`}).join('')}</div></section>`}
function doTransfer(outId){const s=store.get();if(s.transfersLeft<=0)return toast(t('noTransfersLeft'),'error');const result=canTransfer({squadIds:s.squadIds,outId,inId:transferIncomingId,players,budget:s.budget});if(!result.ok)return toast(result.reason==='budget'?t('budgetExceeded'):result.reason==='club'?t('clubLimit'):t('transferRejected'),'error');const newStarting=s.startingIds.map(id=>id===outId?transferIncomingId:id);const cap=s.captainId===outId?transferIncomingId:s.captainId;const vice=s.viceCaptainId===outId?transferIncomingId:s.viceCaptainId;store.set({squadIds:result.next,startingIds:newStarting,budget:result.nextBudget,captainId:cap,viceCaptainId:vice,transfersLeft:Math.max(0,s.transfersLeft-1),transfersMade:s.transfersMade+1});transferIncomingId=null;playerSheetId=null;playTone('success');haptic();toast(t('transferSuccess'));renderApp();}

function renderLeagueDialog(){if(!leagueDialog)return '';const create=leagueDialog==='create';return `<div class="modal-backdrop" data-close-league></div><section class="modal small-modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${create?t('createLeague'):t('joinLeague')}</h2><button data-close-league aria-label="${t('close')}">${icon('x',20)}</button></div><form id="league-form" class="form-stack"><label>${create?t('leagueName'):t('joinCode')}<input name="value" required maxlength="32" placeholder="${create?t('leaguePlaceholder'):'NOVA26'}"></label><button class="primary" type="submit">${create?t('create'):t('join')}</button></form></section>`}

function avatar(name='',size=''){const initials=String(name||'SN').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();return `<span class="avatar ${size}">${escapeHtml(initials)}</span>`}

function bindAppEvents(){document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{const f=fixtures.find(x=>x.id===b.dataset.match);store.set({screen:'matches',moreScreen:null,matchTab:f?.status==='result'?'results':f?.status==='today'?'today':f?.status==='upcoming'?'upcoming':'live'});playerSheetId=null;renderApp()});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{store.set({screen:b.dataset.nav,moreScreen:null});playerSheetId=null;renderApp()});document.querySelectorAll('[data-more]').forEach(b=>b.onclick=()=>{store.set({screen:'more',moreScreen:b.dataset.more});playerSheetId=null;renderApp()});document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{playerSheetId=b.dataset.player;renderApp()});document.querySelectorAll('[data-close-sheet]').forEach(b=>b.onclick=()=>{playerSheetId=null;renderApp()});document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=e=>{e.stopPropagation();transferIncomingId=b.dataset.buy;playerSheetId=null;renderApp()});document.querySelectorAll('[data-formation]').forEach(b=>b.onclick=()=>{const s=store.get(),f=b.dataset.formation,startingIds=recalcStartingXI(s.squadIds,f,players,s.startingIds);const captainId=startingIds.includes(s.captainId)?s.captainId:startingIds.find(id=>playerMap[id].position==='FWD')||startingIds[0];const viceCaptainId=startingIds.includes(s.viceCaptainId)&&s.viceCaptainId!==captainId?s.viceCaptainId:startingIds.find(id=>id!==captainId&&playerMap[id].position==='MID')||startingIds.find(id=>id!==captainId);store.set({formation:f,startingIds,captainId,viceCaptainId});haptic();renderApp()});document.getElementById('save-squad')?.addEventListener('click',()=>{playTone('success');toast(t('saved'))});
 document.querySelectorAll('[data-captain]').forEach(b=>b.onclick=()=>{const s=store.get();if(s.viceCaptainId===b.dataset.captain)store.set({captainId:b.dataset.captain,viceCaptainId:s.captainId});else store.set({captainId:b.dataset.captain});playTone('success');playerSheetId=null;renderApp()});document.querySelectorAll('[data-vice]').forEach(b=>b.onclick=()=>{const s=store.get();if(s.captainId===b.dataset.vice)store.set({viceCaptainId:b.dataset.vice,captainId:s.viceCaptainId});else store.set({viceCaptainId:b.dataset.vice});playerSheetId=null;renderApp()});document.querySelectorAll('[data-toggle-start]').forEach(b=>b.onclick=()=>toggleStart(b.dataset.toggleStart));
 document.getElementById('player-search')?.addEventListener('input',filterMarket);['filter-pos','filter-club','sort-player','filter-price','filter-points','filter-form','filter-ownership','filter-status','filter-difficulty'].forEach(id=>document.getElementById(id)?.addEventListener('change',filterMarket));bindDynamicMarket();document.querySelectorAll('[data-match-tab]').forEach(b=>b.onclick=()=>{store.set({matchTab:b.dataset.matchTab});renderApp()});document.querySelectorAll('[data-more-back]').forEach(b=>b.onclick=()=>{store.set({moreScreen:null});renderApp()});document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{store.set({fixtureWeek:Number(b.dataset.week)});renderApp()});document.querySelectorAll('[data-fixture-view]').forEach(b=>b.onclick=()=>{store.set({fixtureView:b.dataset.fixtureView});renderApp()});document.getElementById('fixture-club')?.addEventListener('change',e=>{store.set({fixtureClub:e.target.value});renderApp()});document.querySelectorAll('[data-league-view]').forEach(b=>b.onclick=()=>{store.set({leagueView:b.dataset.leagueView});renderApp()});document.querySelectorAll('[data-league-id]').forEach(b=>b.onclick=()=>{store.set({activeLeagueId:b.dataset.leagueId});renderApp()});document.querySelectorAll('[data-league-dialog]').forEach(b=>b.onclick=()=>{leagueDialog=b.dataset.leagueDialog;renderApp()});document.querySelectorAll('[data-close-league]').forEach(b=>b.onclick=()=>{leagueDialog=null;renderApp()});document.getElementById('league-form')?.addEventListener('submit',handleLeagueForm);
 document.getElementById('setting-language')?.addEventListener('change',e=>{store.set({language:e.target.value});applyPreferences();renderApp()});document.getElementById('setting-theme')?.addEventListener('change',e=>{store.set({theme:e.target.value});applyPreferences();renderApp()});document.querySelectorAll('[data-setting]').forEach(x=>x.onchange=()=>{store.set({[x.dataset.setting]:x.checked});applyPreferences()});document.getElementById('setting-fullscreen')?.addEventListener('click',requestFullscreen);document.getElementById('install-app')?.addEventListener('click',installApp);document.getElementById('logout')?.addEventListener('click',async()=>{try{await fetch('/api/auth/logout',{method:'POST'})}catch{}store.set({session:null});localStorage.removeItem('sahanova.entered');document.body.classList.remove('app-mode');renderGate()});document.getElementById('demo-admin-login')?.addEventListener('click',()=>{loginDemo(true);store.set({onboardingDone:true,screen:'more',moreScreen:'admin'});renderApp()});document.getElementById('fs-return')?.addEventListener('click',requestFullscreen);
 document.querySelectorAll('[data-close-transfer]').forEach(b=>b.onclick=()=>{transferIncomingId=null;renderApp()});document.querySelectorAll('[data-outgoing]').forEach(b=>b.onclick=()=>{if(!b.classList.contains('disabled'))doTransfer(b.dataset.outgoing)});setupModalA11y();
}
function setupModalA11y(){if(activeModalKeyHandler){document.removeEventListener('keydown',activeModalKeyHandler);activeModalKeyHandler=null}const dialog=document.querySelector('[role=dialog]');if(!dialog)return;const focusable=()=>[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),a[href]')];queueMicrotask(()=>focusable()[0]?.focus());activeModalKeyHandler=e=>{if(e.key==='Escape'){if(playerSheetId)playerSheetId=null;if(transferIncomingId)transferIncomingId=null;if(leagueDialog)leagueDialog=null;renderApp();return}if(e.key!=='Tab')return;const items=focusable();if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};document.addEventListener('keydown',activeModalKeyHandler)}
function bindDynamicMarket(){document.querySelectorAll('#player-market [data-player]').forEach(b=>b.onclick=()=>{playerSheetId=b.dataset.player;renderApp()});document.querySelectorAll('#player-market [data-buy]').forEach(b=>b.onclick=e=>{e.stopPropagation();transferIncomingId=b.dataset.buy;renderApp()})}
function toggleStart(id){const s=store.get(),p=playerMap[id],starting=s.startingIds.includes(id); if(starting){const bench=s.squadIds.filter(x=>!s.startingIds.includes(x)).map(x=>playerMap[x]).find(x=>x.position===p.position);if(!bench)return toast(t('noBenchForPosition'),'error');store.set({startingIds:s.startingIds.map(x=>x===id?bench.id:x),...(s.captainId===id?{captainId:bench.id}:{}),...(s.viceCaptainId===id?{viceCaptainId:bench.id}:{})});}else{const starter=s.startingIds.map(x=>playerMap[x]).find(x=>x.position===p.position);if(!starter)return toast(t('invalidSquad'),'error');store.set({startingIds:s.startingIds.map(x=>x===starter.id?id:x)});}playerSheetId=null;haptic();renderApp()}
function handleLeagueForm(e){e.preventDefault();const value=new FormData(e.currentTarget).get('value').trim();const s=store.get();if(leagueDialog==='create'){const code=Math.random().toString(36).slice(2,8).toUpperCase(),id='l'+Date.now();store.set({leagues:[...s.leagues,{id,name:value,code}],activeLeagueId:id,leagueView:'friends'});toast(`${t('success')}: ${code}`)}else{const id='j'+Date.now();store.set({leagues:[...s.leagues,{id,name:value.toUpperCase()==='ANKARA26'?t('joinedLeagueName'):t('newMiniLeague'),code:value.toUpperCase()}],activeLeagueId:id,leagueView:'friends'});toast(t('success'))}leagueDialog=null;renderApp()}
async function installApp(){if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else toast(t('installUnavailable'),'error')}

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('online',()=>document.getElementById('offline-banner')?.classList.remove('show'));window.addEventListener('offline',()=>document.getElementById('offline-banner')?.classList.add('show'));document.addEventListener('fullscreenchange',()=>{const b=document.getElementById('fullscreen-banner');if(!b)return;const entered=localStorage.getItem('sahanova.entered');b.classList.toggle('show',!!entered&&!document.fullscreenElement&&!window.matchMedia('(display-mode: standalone)').matches)});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&playerSheetId){playerSheetId=null;renderApp()}});
setInterval(()=>{matchTick=(matchTick+1)%60;const liveMinute=document.querySelectorAll('.is-live .match-status span,.live-match .match-card-top>span:first-child');if(liveMinute.length&&store.get().screen==='matches')renderApp();const c=document.getElementById('deadline-count');if(c)c.textContent=countdown()},30000);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
const shortcutScreen=new URLSearchParams(location.search).get('screen');if(['home','team','transfer','matches','more'].includes(shortcutScreen))store.set({screen:shortcutScreen});
async function bootstrap(){
 try{
  const r=await fetch('/api/public/bootstrap',{cache:'no-store'});
  if(r.ok){const d=await r.json();if(d.overrides){applyOverrides(d.overrides);localStorage.setItem('sahanova.admin.overrides',JSON.stringify(d.overrides))}if(d.config)localStorage.setItem('sahanova.admin.config',JSON.stringify(d.config));}
 }catch{}
 applyPreferences();if(!localStorage.getItem('sahanova.entered'))renderGate();else renderAuthOrApp();
}
bootstrap();
